Q: resolving inline javascript unobtrusively A: <p>Loading the javascript locally by declaration in <code>importmap.rb</code> <code>pin &quot;auto-complete&quot;, to: &quot;auto-complete.js&quot;</code> is a positive start.</p>
<p>But as <strong>kudos</strong> @mplungjan pointed out, <code>export default autoComplete;</code> needed to be added the local <code>auto-complete.js</code> file.<br />
<em>a lengthy dialog with AI missed this bit &amp; proceeded to send all conversation participants on a lengthy garden path</em></p>
<p>From there, with the following input field for the view file:</p>
<pre><code>      &lt;%= f.text_field :municipal_other,
        id: &quot;user_municipal_other&quot;, 
        data: {
          controller: &quot;auto-complete&quot;,
          # Map @auto_complete_values -&gt; data-auto-complete-values-value (escape JSON safely)
          &quot;auto-complete-values-value&quot;: @auto_complete_values.to_json,
          &quot;auto-complete-min-chars-value&quot;: 2
        } %&gt;
</code></pre>
<p>in <code>javascript/controllers/auto_complete_controller.js</code> the controller will execute as expected</p>
<pre><code>
import { Controller } from &quot;@hotwired/stimulus&quot;;

/*
  Generic simplified Stimulus controller:
    - Expects server to provide @auto_complete_values (Array).
    - Use data-auto-complete-values-value with JSON (escaped) to pass the array.
    - Optional: data-auto-complete-selector-value to point at the input element
      (useful if controller is on a wrapper).
    - Optional: data-auto-complete-min-chars-value (Number). Default is 2
*/

export default class extends Controller {
  static values = {
    values: Array,
    selector: String,
    minChars: Number,
    menuClass: String
  }

  connect() {
    console.debug(&quot;auto-complete: connect()&quot;, { elementId: this.element.id });

    // Basic sanity: library must be loaded (vendor file sets window.autoComplete)
    if (!window.autoComplete) {
      console.error(&quot;autoComplete library not available on window&quot;);
      return;
    }

    // Stimulus should have parsed the values into an Array; fallback to parsing dataset if needed
    this.choices = this.hasValuesValue ? this.valuesValue : null;
    if (!Array.isArray(this.choices)) {
      const raw = this.element.dataset.autoCompleteValuesValue || this.element.dataset.autoCompleteItemsValue;
      if (raw) {
        try {
          this.choices = JSON.parse(raw);
        } catch (e) {
          console.error(&quot;auto-complete: failed to parse JSON from data attribute&quot;, e, raw);
          this.choices = [];
        }
      } else {
        this.choices = [];
      }
    }

    this.minChars = this.hasMinCharsValue ? this.minCharsValue : 2; // your chosen default
    this.menuClass = this.hasMenuClassValue ? this.menuClassValue : &quot;&quot;;

    console.debug(&quot;auto-complete: parsed choices length=&quot;, this.choices.length, {
      sample: this.choices.slice(0, 5),
      minChars: this.minChars
    });

    // Find the single target input element
    if (this.hasSelectorValue &amp;&amp; this.selectorValue) {
      let el = null;
      try { el = this.element.querySelector(this.selectorValue); } catch (err) { el = null; }
      if (!el) {
        try { el = document.querySelector(this.selectorValue); } catch (err) { el = null; }
      }
      if (!el) {
        console.error(&quot;auto-complete: selector not found:&quot;, this.selectorValue);
        return;
      }
      this.target = el;
    } else {
      // Controller should be attached directly to the input
      this.target = this.element;
    }

    // Sanity log of the target and its dataset (decoded by browser)
    try {
      console.debug(&quot;auto-complete: target element&quot;, {
        id: this.target.id,
        name: this.target.name,
        dataset: this.target.dataset
      });
    } catch (e) {
      console.warn(&quot;auto-complete: couldn't log target dataset&quot;, e);
    }

    // Initialize the autoComplete instance on the single target
    try {
      this.instance = new window.autoComplete({
        selector: this.target,
        minChars: this.minChars,
        menuClass: this.menuClass,
        source: (term, suggest) =&gt; {
          term = term.toLowerCase();
          const suggestions = this.choices.filter(c =&gt; c &amp;&amp; c.toLowerCase().includes(term));
          suggest(suggestions);
        }
      });
      console.debug(&quot;auto-complete: instance created&quot;);
    } catch (e) {
      console.error(&quot;auto-complete: failed to create instance&quot;, e);
    }
  }

  disconnect() {
    if (this.instance &amp;&amp; typeof this.instance.destroy === &quot;function&quot;) {
      try { this.instance.destroy(); } catch (e) { /* ignore */ }
      this.instance = null;
      console.debug(&quot;auto-complete: instance destroyed&quot;);
    }
  }
}
</code></pre>
